  quiet_receipt:{title:'하얀 종이의 소리',day:20,lines:[['타키','영수증 용지 갈고 나니까 자투리가 남았네. 이건 버려야겠다.'],['토모리','타키 쨩… 잠깐만.'],['타키','응? 아직 아무것도 안 찍힌 종이야.'],['토모리','찢을 때 나는 소리가… 빗방울이 창문에 닿는 것 같아.'],['타키','종이 찢는 소리가?'],['토모리','응. 아까는 길게 났는데, 지금은 짧게 났어.'],['타키','이쪽으로 천천히 찢으면 길어지고, 빨리 당기면 짧아져.'],['토모리','…다르다.'],['타키','연습할 때 드럼 소리 고르는 것처럼 듣고 있었어?'],['토모리','응. 같은 비여도, 창문이랑 바닥에 닿는 소리가 다르니까.'],['타키','그럼 이건 아직 버리지 말까? 깨끗한 부분만 잘라 줄게.'],['토모리','고마워. 나중에 생각날 수 있게 노트 사이에 넣어 둘래.'],['타키','그래. 남은 건 내가 정리할게.']]},
  apron_exchange:{title:'앞치마를 빌린 날',day:21,lines:[['아논','잠깐 도와주는 건데, 나도 앞치마 입어도 돼?'],['타키','여분이 있긴 한데… 장식처럼 묶으면 움직이기 불편할걸.'],['아논','알고 있어! 자, 이렇게. 어때?'],['소요','끈이 바닥에 닿겠다. 뒤에서 조금 짧게 묶어 줄게.'],['아논','고마워, 소요링. 이러면 완벽하지?'],['타키','이제 그 쟁반부터 옮겨 줘.']]},
  sound_of_rain:{title:'소리가 겹치는 곳',day:22,when:s=>rainy(),lines:[['라나','빗소리랑 드럼 소리, 같이 들려.'],['타키','연습실 문이 조금 열려 있네. 닫아 둘게.'],['라나','안에서는 어떻게 들릴까?'],['타키','궁금하면 들어가서 들어 봐. 복도에서 뛰지는 말고.'],['라나','응. 릿키도 와.'],['타키','마감 끝나면 갈게. 먼저 가 있어.']]},
  first_order:{title:'첫 주문의 기억',day:23,when:s=>s.endingDays>=5,lines:[['타키','처음 영업하던 날에는 주문표를 어디에 둬야 할지도 헷갈렸지.'],['아논','그땐 내가 없었잖아. 무슨 일이 있었는데?'],['타키','별일은 없었어. 주문표를 찾느라 카운터를 몇 번이나 오갔어.'],['소요','지금은 주문표가 제자리에 있으니까 누구나 확인할 수 있네.'],['타키','응. 바쁜 날을 몇 번 지나고 나서야 정한 자리야.'],['아논','그럼 여기에 놓으면 되는 거지?'],['타키','거긴 다 끝난 주문이야. 아직 안 만든 건 반대쪽.'],['아논','똑같이 생겼는데 어떻게 알아?'],['타키','클립 방향이 다르잖아.'],['소요','처음 보는 사람은 잘 모를 수도 있겠다. 작은 표시를 붙여 둘까?'],['타키','…그게 낫겠네. 바쁠 때 내가 못 보면 다른 사람도 확인할 수 있고.'],['아논','내가 적을게! 완성된 쪽에는 별을 그리고.'],['타키','별보다 글씨가 먼저 보여야 해.'],['아논','알았어. 글씨 옆에 작게 그릴게.'],['소요','후후. 그러면 둘 다 알아볼 수 있겠네.'],['타키','일단 붙이고 내가 한 번 볼게.']]},
  set_table:{title:'한 자리씩',day:24,when:s=>s.upgrades.seats>0,lines:[['소요','좌석이 늘고 나니까 정리 순서도 바뀌었네.'],['타키','안쪽부터 닦지 않으면 손님이 지나갈 때 다시 비켜야 하더라.'],['소요','그럼 나는 문 가까운 쪽을 할게.'],['타키','괜찮아? 너도 연습 끝나고 온 건데.'],['소요','두 사람이라면 금방 끝나. 끝나고 차 마시자.']]},
