  post_morning:{title:'다음 날의 준비',day:32,when:s=>!!s.endingId,lines:[['타키','어제 의자를 다 넣어 둬서 오늘은 꺼내는 것부터네.'],['라나','이거 여기?'],['타키','응, 벽에 너무 붙이지 말고. 사람들이 지나갈 자리는 남겨 둬.'],['라나','이 정도?'],['타키','그 정도면 돼. …도와줘서 고마워.'],['라나','응. 이제 기타 쳐도 돼?']]},
  post_song:{title:'다음에 들을 노래',day:33,when:s=>!!s.endingId&&s.stories.includes('post_morning'),lines:[['아논','다음 공연에서 어떤 곡부터 할까?'],['타키','아직 정하지 않았어. 먼저 다 같이 연습해 보고.'],['토모리','나는… 마지막에 부른 노래를 다시 부르고 싶어.'],['소요','그럼 시작 순서는 연습하면서 생각하자.'],['라나','새로운 것도 하고 싶어.'],['아논','좋아! 정할 게 많네. 일단 음료부터 마시고 시작하자.'],['타키','시간 정해 놓고 마셔. 또 늦으면 안 되니까.']]}
